-- =============================================================================
-- Brightlight Solutions -- DEMO CATALOGUE (placeholder products, v2 model)
-- Safe to run more than once: it first removes any earlier demo rows, then re-adds them.
-- Only touches rows whose product_number starts with 'DEMO-'. Your own products are never changed.
--
-- Run AFTER supabase/schema.sql:
--     Supabase Dashboard -> SQL Editor -> paste this whole file -> Run
-- Images: served from /demo/*.svg in the site's public folder (no storage upload needed).
--
-- What it shows off: categories + category attributes, MRP / % off, brand, multi-option variants
-- (Size x Colour with some sold-out combinations), low stock, a fully sold-out product, ratings.
-- The ratings, review counts and sales numbers are FAKE demo values -- real ones come from customer
-- reviews and orders.
--
-- REMOVE the demo products later (run this in the SQL Editor):
--     delete from public.products where product_number like 'DEMO-%';
-- ...and delete the public/demo folder from the project.
-- =============================================================================

begin;

delete from public.products where product_number like 'DEMO-%';

insert into public.products
  (product_number, name, brand, category_id, subtitle, description, highlights, attributes, option_types, tags,
   badge, featured, images, image_position, delivery_min_days, delivery_max_days,
   rating_avg, rating_count, sales_count, status, created_at)
values
  ('DEMO-001', 'Cotton Kurta Set', 'Kaveri Weaves', (select id from public.categories where name = 'Women Ethnic' limit 1), 'Straight-fit kurta with embroidered placket', 'A breathable everyday kurta with hand-style embroidery at the neckline and cuffs. Soft, pre-washed cotton that stays comfortable through long days and warm weather.', '["100% cotton","Pairs well with white churidar leggings and a light dupatta.","Easy 7-day returns"]'::jsonb, '{"material":"100% cotton","fit":"Regular","occasion":"Festive","care":"Machine wash cold, do not bleach","dimensions":"Length 44 in","weight":"420 g"}'::jsonb, '[{"name":"Size","values":["S","M","L","XL","XXL"]},{"name":"Colour","values":["Indigo","Maroon"]}]'::jsonb, '["women ethnic","kaveri weaves"]'::jsonb, 'Bestseller', true, '["/demo/cotton-kurta-set-1.svg","/demo/cotton-kurta-set-2.svg","/demo/cotton-kurta-set-3.svg"]'::jsonb, '50% 50%', 3, 6, 4.1, 278, 336, 'active', now() - interval '3 minutes'),
  ('DEMO-002', 'Ceramic Table Lamp', 'Hearth & Co', (select id from public.categories where name = 'Home Decor' limit 1), 'Fabric shade with brass-finish base', 'Warm, diffused light for bedside tables and reading corners. A hand-glazed ceramic base with a brass-finish stem and a linen drum shade.', '["Ceramic, linen shade","Use with a warm 7W LED bulb (E27, not included).","Easy 7-day returns"]'::jsonb, '{"material":"Ceramic, linen shade","dimensions":"38 x 22 cm","weight":"1.1 kg"}'::jsonb, '[]'::jsonb, '["home decor","hearth & co"]'::jsonb, 'Trending', true, '["/demo/ceramic-table-lamp-1.svg","/demo/ceramic-table-lamp-2.svg","/demo/ceramic-table-lamp-3.svg"]'::jsonb, '50% 50%', 3, 6, 3.8, 85, 121, 'active', now() - interval '44 minutes'),
  ('DEMO-003', 'Vitamin C Face Serum 30 ml', 'Glow Theory', (select id from public.categories where name = 'Skincare' limit 1), 'Brightening serum with hyaluronic acid', 'A lightweight daily serum with 10% vitamin C and hyaluronic acid to even out tone and add glow. Absorbs fast, no sticky finish. Patch test before first use.', '["Dermatologically tested","Follow with a moisturiser and sunscreen in the morning.","Easy 7-day returns"]'::jsonb, '{"skin_type":"All skin types","volume":"30 ml","ingredients":"Dermatologically tested","shelf_life":"24 months","weight":"95 g"}'::jsonb, '[]'::jsonb, '["skincare","glow theory"]'::jsonb, 'Bestseller', true, '["/demo/vitamin-c-face-serum-30-ml-1.svg","/demo/vitamin-c-face-serum-30-ml-2.svg","/demo/vitamin-c-face-serum-30-ml-3.svg"]'::jsonb, '50% 50%', 3, 6, 4.6, 698, 804, 'active', now() - interval '85 minutes'),
  ('DEMO-004', '20W USB-C Fast Charger', 'Pixelon', (select id from public.categories where name = 'Mobile Accessories' limit 1), 'Includes 1 m USB-C cable', 'Charge compatible phones from 0 to 50% in about 30 minutes. Compact enough to travel with, with over-heat and short-circuit protection built in.', '["Fire-retardant ABS","Easy 7-day returns"]'::jsonb, '{"warranty":"1 year","material":"Fire-retardant ABS","dimensions":"6 x 5 x 3 cm","power":"20 W","weight":"85 g"}'::jsonb, '[]'::jsonb, '["mobile accessories","pixelon"]'::jsonb, 'Bestseller', true, '["/demo/20w-usb-c-fast-charger-1.svg","/demo/20w-usb-c-fast-charger-2.svg","/demo/20w-usb-c-fast-charger-3.svg"]'::jsonb, '50% 50%', 3, 6, 0, 0, 590, 'active', now() - interval '126 minutes'),
  ('DEMO-005', 'Everyday Laptop Backpack', 'Stride Lab', (select id from public.categories where name = 'Bags' limit 1), 'Fits 15.6 in laptop, water-resistant', 'A roomy, padded backpack with a laptop sleeve, a quick-access front pocket and breathable straps. Water-resistant fabric keeps the contents dry in light rain.', '["Water-resistant polyester","Easy 7-day returns"]'::jsonb, '{"material":"Water-resistant polyester","dimensions":"45 x 30 x 15 cm","weight":"650 g"}'::jsonb, '[]'::jsonb, '["bags","stride lab"]'::jsonb, 'Bestseller', true, '["/demo/everyday-laptop-backpack-1.svg","/demo/everyday-laptop-backpack-2.svg","/demo/everyday-laptop-backpack-3.svg"]'::jsonb, '50% 50%', 3, 6, 4.1, 313, 375, 'active', now() - interval '167 minutes'),
  ('DEMO-006', 'Printed Anarkali Dress', 'Kaveri Weaves', (select id from public.categories where name = 'Women Ethnic' limit 1), 'Flared festive dress with floral print', 'A flowing festive dress with a fitted bodice and a full flare. The light rayon blend drapes beautifully and is easy to care for.', '["Rayon blend","Team it with jhumka earrings and flat sandals for a complete festive look.","Easy 7-day returns"]'::jsonb, '{"material":"Rayon blend","fit":"Regular","occasion":"Festive","care":"Machine wash cold, do not bleach","dimensions":"Length 48 in","weight":"480 g"}'::jsonb, '[{"name":"Size","values":["S","M","L","XL"]}]'::jsonb, '["women ethnic","kaveri weaves"]'::jsonb, 'New', true, '["/demo/printed-anarkali-dress-1.svg","/demo/printed-anarkali-dress-2.svg","/demo/printed-anarkali-dress-3.svg"]'::jsonb, '50% 50%', 3, 6, 0, 0, 161, 'active', now() - interval '208 minutes'),
  ('DEMO-007', 'Geometric Wall Clock', 'Hearth & Co', (select id from public.categories where name = 'Home Decor' limit 1), 'Silent sweep movement, 30 cm', 'A clean, modern wall clock with a silent sweep movement so there is no ticking at night. Easy to read from across the room.', '["MDF, glass","Needs 1 AA battery (not included).","Easy 7-day returns"]'::jsonb, '{"material":"MDF, glass","dimensions":"Dia 30 cm","weight":"620 g"}'::jsonb, '[]'::jsonb, '["home decor","hearth & co"]'::jsonb, null, true, '["/demo/geometric-wall-clock-1.svg","/demo/geometric-wall-clock-2.svg","/demo/geometric-wall-clock-3.svg"]'::jsonb, '50% 50%', 3, 6, 4.6, 734, 843, 'active', now() - interval '249 minutes'),
  ('DEMO-008', 'Hydrating Day Cream 50 g', 'Glow Theory', (select id from public.categories where name = 'Skincare' limit 1), 'SPF 20, non-greasy', 'A light, non-greasy day cream with SPF 20 and 24-hour hydration. Sinks in quickly and sits well under makeup.', '["Dermatologically tested","Easy 7-day returns"]'::jsonb, '{"skin_type":"All skin types","volume":"50 g","ingredients":"Dermatologically tested","shelf_life":"24 months","weight":"140 g"}'::jsonb, '[]'::jsonb, '["skincare","glow theory"]'::jsonb, null, true, '["/demo/hydrating-day-cream-50-g-1.svg","/demo/hydrating-day-cream-50-g-2.svg","/demo/hydrating-day-cream-50-g-3.svg"]'::jsonb, '50% 50%', 3, 6, 0, 0, 629, 'active', now() - interval '290 minutes'),
  ('DEMO-009', 'True Wireless Earbuds', 'Tonewave', (select id from public.categories where name = 'Audio' limit 1), 'Bluetooth 5.3, 30 h playtime with case', 'Punchy bass, clear calls and up to 30 hours of playtime with the charging case. Touch controls, low-latency gaming mode and IPX4 splash resistance.', '["ABS plastic","Compatible with Android and iOS.","Easy 7-day returns"]'::jsonb, '{"warranty":"1 year","material":"ABS plastic","dimensions":"Case 6 x 4 x 3 cm","connectivity":"Bluetooth 5.3","weight":"45 g"}'::jsonb, '[]'::jsonb, '["audio","tonewave"]'::jsonb, 'Trending', true, '["/demo/true-wireless-earbuds-1.svg","/demo/true-wireless-earbuds-2.svg","/demo/true-wireless-earbuds-3.svg"]'::jsonb, '50% 50%', 3, 6, 4.2, 348, 415, 'active', now() - interval '331 minutes'),
  ('DEMO-010', 'Faux Leather Handbag', 'Meraki', (select id from public.categories where name = 'Bags' limit 1), 'Structured shoulder bag with zip pocket', 'A structured everyday bag with a magnetic flap, inner zip pocket and a comfortable top handle. Roomy enough for a tablet and daily essentials.', '["PU leather","Easy 7-day returns"]'::jsonb, '{"material":"PU leather","dimensions":"30 x 22 x 11 cm","weight":"620 g"}'::jsonb, '[]'::jsonb, '["bags","meraki"]'::jsonb, 'Trending', false, '["/demo/faux-leather-handbag-1.svg","/demo/faux-leather-handbag-2.svg","/demo/faux-leather-handbag-3.svg"]'::jsonb, '50% 50%', 3, 6, 3.9, 156, 200, 'active', now() - interval '372 minutes'),
  ('DEMO-011', 'Floral Midi Dress', 'Urban Thread', (select id from public.categories where name = 'Women Western' limit 1), 'Fit-and-flare midi with adjustable straps', 'A light, flattering midi dress with adjustable straps and a swishy skirt. Wrinkle-resistant fabric that goes from brunch to evening.', '["Poly crepe","Easy 7-day returns"]'::jsonb, '{"material":"Poly crepe","fit":"Regular","occasion":"Casual","care":"Machine wash cold, do not bleach","dimensions":"Length 42 in","weight":"350 g"}'::jsonb, '[{"name":"Size","values":["S","M","L","XL"]}]'::jsonb, '["women western","urban thread"]'::jsonb, 'Trending', false, '["/demo/floral-midi-dress-1.svg","/demo/floral-midi-dress-2.svg","/demo/floral-midi-dress-3.svg"]'::jsonb, '50% 50%', 3, 6, 4.7, 769, 883, 'active', now() - interval '413 minutes'),
  ('DEMO-012', 'Velvet Cushion Cover (Set of 2)', 'Hearth & Co', (select id from public.categories where name = 'Furnishing' limit 1), '16 x 16 inch, concealed zip', 'Instantly refresh your sofa or bed. Plush velvet covers with a concealed zip and neat piped edges. Cushion inserts not included.', '["Soft velvet","Easy 7-day returns"]'::jsonb, '{"material":"Soft velvet","dimensions":"40 x 40 cm","weight":"240 g"}'::jsonb, '[]'::jsonb, '["furnishing","hearth & co"]'::jsonb, 'Bestseller', true, '["/demo/velvet-cushion-cover-set-of-2-1.svg","/demo/velvet-cushion-cover-set-of-2-2.svg","/demo/velvet-cushion-cover-set-of-2-3.svg"]'::jsonb, '50% 50%', 3, 6, 0, 0, 669, 'active', now() - interval '454 minutes'),
  ('DEMO-013', 'Matte Liquid Lipstick', 'Glow Theory', (select id from public.categories where name = 'Makeup' limit 1), 'Long-wear, smudge-proof colour', 'Rich, one-swipe colour with a comfortable matte finish that lasts through meals and meetings.', '["Cruelty-free formula","Easy 7-day returns"]'::jsonb, '{"skin_type":"All skin types","volume":"4 ml","ingredients":"Cruelty-free formula","shelf_life":"24 months","weight":"45 g"}'::jsonb, '[]'::jsonb, '["makeup","glow theory"]'::jsonb, 'Trending', false, '["/demo/matte-liquid-lipstick-1.svg","/demo/matte-liquid-lipstick-2.svg","/demo/matte-liquid-lipstick-3.svg"]'::jsonb, '50% 50%', 3, 6, 4.2, 384, 454, 'active', now() - interval '495 minutes'),
  ('DEMO-014', 'Over-Ear Wireless Headphones', 'Tonewave', (select id from public.categories where name = 'Audio' limit 1), '40 mm drivers, up to 50 h battery', 'Big, immersive sound with soft protein-leather ear cushions for all-day comfort. Fold-flat design, built-in mic and up to 50 hours of battery life.', '["Memory-foam ear cushions","Easy 7-day returns"]'::jsonb, '{"warranty":"1 year","material":"Memory-foam ear cushions","dimensions":"Foldable","connectivity":"Bluetooth 5.3","weight":"260 g"}'::jsonb, '[]'::jsonb, '["audio","tonewave"]'::jsonb, 'Limited Deal', false, '["/demo/over-ear-wireless-headphones-1.svg","/demo/over-ear-wireless-headphones-2.svg","/demo/over-ear-wireless-headphones-3.svg"]'::jsonb, '50% 50%', 3, 6, 4, 191, 240, 'active', now() - interval '536 minutes'),
  ('DEMO-015', 'Running Sneakers', 'Stride Lab', (select id from public.categories where name = 'Footwear' limit 1), 'Lightweight mesh, cushioned sole', 'Breathable mesh, a cushioned EVA midsole and a grippy outsole for daily runs and long walks. Light enough that you forget you are wearing them.', '["Mesh upper, EVA sole","Easy 7-day returns"]'::jsonb, '{"material":"Mesh upper, EVA sole","dimensions":"UK sizes 6-10","weight":"560 g (pair)"}'::jsonb, '[{"name":"Size","values":["6","7","8","9","10"]},{"name":"Colour","values":["Black","White"]}]'::jsonb, '["footwear","stride lab"]'::jsonb, 'Bestseller', true, '["/demo/running-sneakers-1.svg","/demo/running-sneakers-2.svg","/demo/running-sneakers-3.svg"]'::jsonb, '50% 50%', 3, 6, 4.7, 805, 25, 'active', now() - interval '577 minutes'),
  ('DEMO-016', 'Ribbed Crop Top', 'Urban Thread', (select id from public.categories where name = 'Women Western' limit 1), 'Stretch ribbed knit, round neck', 'A soft stretch rib that hugs without feeling tight. A wardrobe staple that layers under jackets or sits on its own.', '["Cotton elastane","Easy 7-day returns"]'::jsonb, '{"material":"Cotton elastane","fit":"Regular","occasion":"Casual","care":"Machine wash cold, do not bleach","dimensions":"Length 17 in","weight":"160 g"}'::jsonb, '[{"name":"Size","values":["XS","S","M","L"]}]'::jsonb, '["women western","urban thread"]'::jsonb, null, false, '["/demo/ribbed-crop-top-1.svg","/demo/ribbed-crop-top-2.svg","/demo/ribbed-crop-top-3.svg"]'::jsonb, '50% 50%', 3, 6, 0, 0, 708, 'active', now() - interval '618 minutes'),
  ('DEMO-017', 'Textured Ceramic Vase', 'Hearth & Co', (select id from public.categories where name = 'Home Decor' limit 1), 'Hand-finished tabletop vase', 'A rounded, hand-finished vase that looks lovely with fresh flowers and just as good empty on a shelf.', '["Glazed ceramic","Easy 7-day returns"]'::jsonb, '{"material":"Glazed ceramic","dimensions":"Height 24 cm","weight":"780 g"}'::jsonb, '[]'::jsonb, '["home decor","hearth & co"]'::jsonb, null, false, '["/demo/textured-ceramic-vase-1.svg","/demo/textured-ceramic-vase-2.svg","/demo/textured-ceramic-vase-3.svg"]'::jsonb, '50% 50%', 3, 6, 4.3, 419, 494, 'active', now() - interval '659 minutes'),
  ('DEMO-018', 'Eyeshadow Palette (8 Shades)', 'Glow Theory', (select id from public.categories where name = 'Makeup' limit 1), 'Matte and shimmer, highly pigmented', 'Eight blendable shades from soft neutrals to a bold shimmer. Buildable colour with minimal fall-out.', '["Cruelty-free formula","Easy 7-day returns"]'::jsonb, '{"skin_type":"All skin types","volume":"8 x 1.5 g","ingredients":"Cruelty-free formula","shelf_life":"24 months","weight":"90 g"}'::jsonb, '[]'::jsonb, '["makeup","glow theory"]'::jsonb, 'New', true, '["/demo/eyeshadow-palette-8-shades-1.svg","/demo/eyeshadow-palette-8-shades-2.svg","/demo/eyeshadow-palette-8-shades-3.svg"]'::jsonb, '50% 50%', 3, 6, 0, 0, 279, 'active', now() - interval '700 minutes'),
  ('DEMO-019', 'Portable Bluetooth Speaker', 'Tonewave', (select id from public.categories where name = 'Audio' limit 1), '20 W stereo, IPX6 water resistant', 'Room-filling 20 W sound in a travel-friendly body. IPX6 water resistance, 12 hours of playtime and a carry loop for the beach or the balcony.', '["Fabric grille, ABS","Easy 7-day returns"]'::jsonb, '{"warranty":"1 year","material":"Fabric grille, ABS","dimensions":"18 x 8 x 8 cm","connectivity":"Bluetooth 5.3","weight":"640 g"}'::jsonb, '[]'::jsonb, '["audio","tonewave"]'::jsonb, null, false, '["/demo/portable-bluetooth-speaker-1.svg","/demo/portable-bluetooth-speaker-2.svg","/demo/portable-bluetooth-speaker-3.svg"]'::jsonb, '50% 50%', 3, 6, 4.8, 34, 65, 'active', now() - interval '741 minutes'),
  ('DEMO-020', 'Casual Flat Sandals', 'Meraki', (select id from public.categories where name = 'Footwear' limit 1), 'Cushioned footbed, adjustable strap', 'Easy flat sandals with a cushioned footbed and a non-slip sole. Comfortable from morning to evening.', '["Synthetic, TPR sole","Easy 7-day returns"]'::jsonb, '{"material":"Synthetic, TPR sole","dimensions":"UK sizes 5-8","weight":"300 g (pair)"}'::jsonb, '[{"name":"Size","values":["5","6","7","8"]}]'::jsonb, '["footwear","meraki"]'::jsonb, null, false, '["/demo/casual-flat-sandals-1.svg","/demo/casual-flat-sandals-2.svg","/demo/casual-flat-sandals-3.svg"]'::jsonb, '50% 50%', 3, 6, 0, 0, 748, 'active', now() - interval '782 minutes'),
  ('DEMO-021', 'Classic Polo T-Shirt', 'Urban Thread', (select id from public.categories where name = 'Men' limit 1), 'Regular fit, pique cotton', 'The polo that works everywhere. Breathable pique cotton, a structured collar that holds its shape and a two-button placket.', '["100% pique cotton","Wear with chinos or dark denim.","Easy 7-day returns"]'::jsonb, '{"material":"100% pique cotton","fit":"Regular","occasion":"Casual","care":"Machine wash cold, do not bleach","dimensions":"Length 28 in","weight":"230 g"}'::jsonb, '[{"name":"Size","values":["S","M","L","XL","XXL"]},{"name":"Colour","values":["Navy","White"]}]'::jsonb, '["men","urban thread"]'::jsonb, 'Bestseller', true, '["/demo/classic-polo-t-shirt-1.svg","/demo/classic-polo-t-shirt-2.svg","/demo/classic-polo-t-shirt-3.svg"]'::jsonb, '50% 50%', 3, 6, 4.3, 455, 533, 'active', now() - interval '823 minutes'),
  ('DEMO-022', 'Non-Stick Frying Pan 24 cm', 'Hearth & Co', (select id from public.categories where name = 'Kitchen & Dining' limit 1), 'Induction-ready, PFOA-free coating', 'Even heating, a slick PFOA-free coating and a cool-touch handle. Works on gas and induction hobs.', '["Aluminium, non-stick coating","Easy 7-day returns"]'::jsonb, '{"material":"Aluminium, non-stick coating","dimensions":"Dia 24 cm","weight":"780 g"}'::jsonb, '[]'::jsonb, '["kitchen & dining","hearth & co"]'::jsonb, 'Limited Deal', false, '["/demo/non-stick-frying-pan-24-cm-1.svg","/demo/non-stick-frying-pan-24-cm-2.svg","/demo/non-stick-frying-pan-24-cm-3.svg"]'::jsonb, '50% 50%', 3, 6, 4.1, 262, 319, 'active', now() - interval '864 minutes'),
  ('DEMO-023', 'Argan Hair Oil 100 ml', 'Glow Theory', (select id from public.categories where name = 'Hair Care' limit 1), 'Frizz control and shine, non-sticky', 'A lightweight oil blend that tames frizz and adds shine without weighing hair down. Use on damp or dry hair.', '["Argan and almond oil blend","Easy 7-day returns"]'::jsonb, '{"skin_type":"All skin types","volume":"100 ml","ingredients":"Argan and almond oil blend","shelf_life":"24 months","weight":"150 g"}'::jsonb, '[]'::jsonb, '["hair care","glow theory"]'::jsonb, null, false, '["/demo/argan-hair-oil-100-ml-1.svg","/demo/argan-hair-oil-100-ml-2.svg","/demo/argan-hair-oil-100-ml-3.svg"]'::jsonb, '50% 50%', 3, 6, 3.8, 70, 104, 'active', now() - interval '905 minutes'),
  ('DEMO-024', 'Fitness Smart Watch', 'Pixelon', (select id from public.categories where name = 'Smart Gadgets' limit 1), '1.8 in display, heart-rate and SpO2', 'Track steps, sleep, heart rate and blood oxygen on a bright 1.8 inch display. 100+ sports modes, call alerts and up to 7 days of battery.', '["Alloy case, silicone strap","Easy 7-day returns"]'::jsonb, '{"warranty":"1 year","material":"Alloy case, silicone strap","dimensions":"44 mm","connectivity":"Bluetooth 5.3","weight":"48 g"}'::jsonb, '[]'::jsonb, '["smart gadgets","pixelon"]'::jsonb, 'Bestseller', true, '["/demo/fitness-smart-watch-1.svg","/demo/fitness-smart-watch-2.svg","/demo/fitness-smart-watch-3.svg"]'::jsonb, '50% 50%', 3, 6, 0, 0, 787, 'active', now() - interval '946 minutes'),
  ('DEMO-025', 'Gold-Plated Jhumka Earrings', 'Meraki', (select id from public.categories where name = 'Jewellery' limit 1), 'Pearl drops, anti-tarnish finish', 'Traditional jhumkas with a pearl fringe and an anti-tarnish gold finish. Light enough for all-day wear.', '["Brass, gold plating, faux pearls","Store in the pouch provided, away from perfume and water.","Easy 7-day returns"]'::jsonb, '{"material":"Brass, gold plating, faux pearls","dimensions":"5 cm drop","weight":"28 g (pair)"}'::jsonb, '[]'::jsonb, '["jewellery","meraki"]'::jsonb, 'New', false, '["/demo/gold-plated-jhumka-earrings-1.svg","/demo/gold-plated-jhumka-earrings-2.svg","/demo/gold-plated-jhumka-earrings-3.svg"]'::jsonb, '50% 50%', 3, 6, 0, 0, 573, 'active', now() - interval '987 minutes'),
  ('DEMO-026', 'Slim Fit Denim Jacket', 'Urban Thread', (select id from public.categories where name = 'Men' limit 1), 'Mid-wash stretch denim with contrast stitching', 'A timeless trucker jacket cut slim through the body, with a hint of stretch for easy movement. Gets better with every wash.', '["Cotton denim, 2% elastane","Layer over a plain tee or polo.","Easy 7-day returns"]'::jsonb, '{"material":"Cotton denim, 2% elastane","fit":"Slim","occasion":"Casual","care":"Machine wash cold, do not bleach","dimensions":"Length 25 in","weight":"780 g"}'::jsonb, '[{"name":"Size","values":["S","M","L","XL","XXL"]},{"name":"Colour","values":["Light Blue","Charcoal"]}]'::jsonb, '["men","urban thread"]'::jsonb, 'Limited Deal', false, '["/demo/slim-fit-denim-jacket-1.svg","/demo/slim-fit-denim-jacket-2.svg","/demo/slim-fit-denim-jacket-3.svg"]'::jsonb, '50% 50%', 3, 6, 4.1, 298, 358, 'active', now() - interval '1028 minutes'),
  ('DEMO-027', 'Insulated Steel Bottle 750 ml', 'Hearth & Co', (select id from public.categories where name = 'Kitchen & Dining' limit 1), 'Keeps cold 24 h, hot 12 h', 'Double-wall vacuum insulation keeps drinks cold for 24 hours and hot for 12. Leak-proof lid and a slim body that fits most bag pockets and cup holders.', '["Stainless steel 304","Easy 7-day returns"]'::jsonb, '{"material":"Stainless steel 304","dimensions":"Height 26 cm","weight":"360 g"}'::jsonb, '[]'::jsonb, '["kitchen & dining","hearth & co"]'::jsonb, 'Bestseller', true, '["/demo/insulated-steel-bottle-750-ml-1.svg","/demo/insulated-steel-bottle-750-ml-2.svg","/demo/insulated-steel-bottle-750-ml-3.svg"]'::jsonb, '50% 50%', 3, 6, 3.9, 105, 144, 'active', now() - interval '1069 minutes'),
